INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Kundenstruktur in der IT immer gleich bleibt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sie verändert sich mit Markt"}, {"text": "Ja", "correct": false, "because": "Zu statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich die Kundenstruktur für IT-Dienstleistungen analysiere?', 3, '[{"text": "Kundenbedürfnisse", "correct": true, "because": "Steuert Angebot"}, {"text": "Schnelle Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Firmendesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Kundenstruktur in der IT?', 5, '[{"text": "Unternehmensgröße", "correct": true, "because": "Bestimmt Bedarf"}, {"text": "Budget", "correct": true, "because": "Beeinflusst Kaufkraft"}, {"text": "Büroausstattung", "correct": false, "because": "Kein direkter Faktor"}, {"text": "Marketingfarben", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Kundenstruktur hilft bei der Zielgruppenansprache. b) Sie ist immer stabil.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Struktur wandelbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Kundenstruktur für ein IT-Projekt analysiere?', 4, '[{"text": "Kundensegmente", "correct": false, "because": "Definieren Zielgruppen"}, {"text": "Kaufverhalten", "correct": false, "because": "Zeigt Präferenzen"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Kundenstruktur nur aus Geschäftskunden besteht?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch Privatkunden"}, {"text": "Ja", "correct": false, "because": "Zu einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich die Kundenstruktur in der IT analysiere?', 3, '[{"text": "Angebot optimieren", "correct": true, "because": "Passt Dienstleistungen an"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Sekundär"}, {"text": "Weniger Kunden", "correct": false, "because": "Kein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale prägen die Kundenstruktur in der IT?', 5, '[{"text": "Branche", "correct": true, "because": "Beeinflusst Bedarf"}, {"text": "Technologienutzung", "correct": true, "because": "Zeigt Präferenzen"}, {"text": "Bürogröße", "correct": false, "because": "Weniger relevant"}, {"text": "Firmenfarben", "correct": false, "because": "Ästhetisch, nicht strukturell"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Kundenstruktur hilft bei der Preisgestaltung. b) Sie bleibt über Jahre gleich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Struktur verändert sich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Kundenstruktur für IT-Dienstleistungen zu verstehen?', 4, '[{"text": "Kundendaten", "correct": false, "because": "Grundlage der Analyse"}, {"text": "Markttrends", "correct": false, "because": "Zeigen Veränderungen"}, {"text": "Bürodeko", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Besteht die Kundenstruktur nur aus großen Firmen?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch KMU und Privat"}, {"text": "Ja", "correct": false, "because": "Zu eng gefasst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Analyse der Kundenstruktur?', 4, '[{"text": "Zielgerichtete Angebote", "correct": true, "because": "Passt an Bedarf"}, {"text": "Bessere Planung", "correct": true, "because": "Antizipiert Nachfrage"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Kundenstruktur nur technische Bedürfnisse zeigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch Budget und Größe"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um die Kundenstruktur für ein IT-Projekt zu analysieren?', 3, '[{"text": "Kundenbefragung", "correct": true, "because": "Liefert direkte Daten"}, {"text": "Zufallsauswahl", "correct": false, "because": "Ungenau"}, {"text": "Firmenlogo", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Kundenstruktur beeinflusst die Produktentwicklung. b) Sie ist immer homogen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Struktur vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Kundenstrukturanalyse?', 5, '[{"text": "Kundengröße", "correct": true, "because": "Beeinflusst Bedarf"}, {"text": "Kaufverhalten", "correct": true, "because": "Zeigt Trends"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Strukturfaktor"}, {"text": "Marketingbudget", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich die Kundenstruktur für IT-Lösungen prüfe?', 3, '[{"text": "Kundensegmentierung", "correct": false, "because": "Definiert Gruppen"}, {"text": "Marktposition", "correct": false, "because": "Zeigt Relevanz"}, {"text": "Firmenfarben", "correct": true, "because": "Kein Analysefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ändert sich die Kundenstruktur in der IT nie?', 3, '[{"text": "Nein", "correct": true, "because": "Passt sich Markt an"}, {"text": "Ja", "correct": false, "because": "Struktur dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Kundenstruktur nur lokale Kunden umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Auch global möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich die Kundenstruktur für IT-Dienste analysiere?', 4, '[{"text": "Kundenvielfalt", "correct": true, "because": "Zeigt Marktbreite"}, {"text": "Schnelle Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]');
